// Server-side SEO helpers (metadata, sitemap, JSON-LD). No client imports here.
import type { Metadata } from "next";
import type { Post, Profile, PublicSettings } from "./types";

/** Default link-preview image (generated by app/opengraph-image.tsx). */
export const DEFAULT_OG = "/opengraph-image";

export const SITE_URL = (process.env.NEXT_PUBLIC_SITE_URL ?? "http://localhost:3000").replace(/\/$/, "");
const API = (process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000").replace(/\/$/, "");

/** Unauthenticated, cached fetch from the API (what search engines and link previews see). */
export async function apiGet<T>(path: string, revalidate = 60): Promise<T | null> {
  try {
    const res = await fetch(`${API}/api/v1${path}`, { next: { revalidate } });
    return res.ok ? ((await res.json()) as T) : null;
  } catch {
    return null;
  }
}

export const getSiteSettings = () => apiGet<PublicSettings>("/settings/public", 30);
export const getProfile = async (username: string) => (await apiGet<{ user: Profile }>(`/users/${encodeURIComponent(username)}`))?.user ?? null;
export const getPost = async (id: string) => (await apiGet<{ post: Post }>(`/posts/${encodeURIComponent(id)}`))?.post ?? null;

export function snippet(text: string, max = 155) {
  const t = text.replace(/\s+/g, " ").trim();
  return t.length > max ? `${t.slice(0, max - 1).trimEnd()}…` : t;
}

/** Private, per-user pages: never indexed, never cached by crawlers. */
export function privatePage(title: string, description?: string): Metadata {
  return { title, description, robots: { index: false, follow: false, nocache: true } };
}

/** Safe JSON-LD: prevents `</script>` breaking out of the tag. */
export function jsonLd(data: unknown) {
  return { __html: JSON.stringify(data).replace(/</g, "\\u003c") };
}
